// Extracts brand colours + SVG path data from simple-icons (CC0) into compact,
// generated files for the app and the browser extension. Only path strings are
// shipped: the UI draws them inside its own <svg>, so no third-party SVG markup
// is ever rendered. Runs before `vite` (see package.json); outputs are gitignored.
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import * as si from "simple-icons";

const here = dirname(fileURLToPath(import.meta.url));
const icons = {};
for (const icon of Object.values(si)) {
  if (icon && typeof icon === "object" && icon.slug && icon.path) icons[icon.slug] = [icon.hex, icon.path];
}
const json = JSON.stringify(icons);
const banner = "// Generated by scripts/gen-brand-icons.mjs from simple-icons (CC0-1.0). Do not edit.\n";

writeFileSync(join(here, "../src/assets/brand-icons.js"), `${banner}export default ${json};\n`);
// The extension has no bundler: expose the same data as a global for popup.js.
writeFileSync(join(here, "../../../extension/brand-icons.js"), `${banner}globalThis.KRYPTOS_BRAND_ICONS = ${json};\n`);
console.log(`brand icons: ${Object.keys(icons).length}`);
